export interface IPRiskResponse {
  /** Id of the API session created for this request. Store it with `vendor_data` if you need to correlate the result with later webhooks or console activity. */
  request_id: string;
  /** Decision for this API session: `In Review` on network or country-mismatch risk, otherwise `Approved`. */
  status: "Approved" | "In Review" | (string & {});
  /** Echo of the `vendor_data` you sent, `null` when you did not send one. */
  vendor_data?: string | null;
  /** Echo of the `metadata` you sent, `null` when you did not send one. */
  metadata?: Record<string, unknown> | null;
  /** Timestamp of this response. */
  created_at: Date;
  /** IP risk result. Individual enrichment fields can be `null` when the lookup returned no usable data. */
  ip?: IPRiskResponseIp;
}

/** IP risk result. Individual enrichment fields can be `null` when the lookup returned no usable data. */
export interface IPRiskResponseIp {
  /** `In Review` when the resolved country conflicts with `claimed_country`, or when the address is associated with VPN, Tor, or data-center infrastructure. Otherwise `Approved`. */
  status: "Approved" | "In Review" | (string & {});
  /** The scored address. `null` when no enrichment source returned usable data. */
  ip_address?: string | null;
  /** Resolved country name. */
  ip_country?: string | null;
  /** Resolved country code. Compare countries through `country_mismatch` instead of comparing raw country strings yourself. */
  ip_country_code?: string | null;
  /** Resolved state or region. */
  ip_state?: string | null;
  /** Resolved city. */
  ip_city?: string | null;
  /** Approximate network geolocation, not a precise device location. */
  latitude?: number | null;
  /** Approximate network geolocation, not a precise device location. */
  longitude?: number | null;
  /** Internet service provider serving the address. */
  isp?: string | null;
  /** Organization owning the address block. */
  organization?: string | null;
  /** `true` when the address is associated with VPN or Tor infrastructure. */
  is_vpn_or_tor?: boolean | null;
  /** `true` when the address belongs to a hosting or data-center network. */
  is_data_center?: boolean | null;
  /** Time zone of the resolved location. */
  time_zone?: string | null;
  /** UTC offset of the resolved location. */
  time_zone_offset?: string | null;
  /** Autonomous system number. */
  asn_number?: number | null;
  /** Organization operating the autonomous system. */
  asn_organization?: string | null;
  /** Connection classification (e.g., `cellular`, `hosting`). */
  connection_type?: string | null;
  /** Mobile carrier when the address is on a mobile network. */
  carrier?: string | null;
  /** Proxy classification when the address is behind a proxy. */
  proxy_type?: string | null;
  /** Echo of the `claimed_country` you sent. */
  claimed_country?: string | null;
  /** `true` when the resolved country differs from `claimed_country`. `null` when no enrichment data or no claimed country is available. */
  country_mismatch?: boolean | null;
  /** Free-form network-threat evidence from the enrichment source (e.g., `is_proxy`, `is_tor`). Empty object when no enrichment data is available. Treat as diagnostic detail, not a stable contract. */
  threat: Record<string, unknown>;
}

/** An address the registry states, in the same shape for every country and registry source. Every key is always present; a part the registry does not publish is null. */
export interface KYBRegistryAddress {
  /** Address type in lower case: `registered` for the registered office; other types as the registry names them (for example `postal`, `office`). `null` when the registry does not say what the address is. */
  type: string | null;
  /** The full address as one line. Always present on every address. */
  address: string;
  /** Street and number. */
  street: string | null;
  /** City or locality. */
  city: string | null;
  /** Postal code. */
  postal_code: string | null;
  /** Region, state or province. */
  region: string | null;
  /** ISO 3166-1 alpha-2 country code. */
  country_code: string | null;
  /** The registry's own label for the address, when it gives one. */
  description: string | null;
}

/** An activity the registry classifies the company under, in the same shape for every country and registry source. */
export interface KYBRegistryIndustry {
  /** Activity code as the registry prints it (for example `73110`). */
  code: string | null;
  /** Activity label, when the registry publishes one. */
  description: string | null;
  /** Classification system, one name per system whichever source reported it: `UK SIC 2007`, `US SIC`, `NACE Rev. 2`, `NACE Rev. 2.1`, `NAF Rev. 2`, `CNAE`, `SBI`, `NOGA 2008`, `CAE Rev. 4`, `Canada SIC 1977`; other national systems keep the registry's own name. Null when the registry does not name the system. */
  scheme: string | null;
  /** True for the company's main activity. Exactly one entry is primary when the list is not empty. */
  is_primary: boolean;
}

/** The outcome of the ownership (Shareholders / UBO) tier, in the same shape for every country and registry source. */
export interface KYBRegistryOwnership {
  /** `delivered` when the registry published ownership; `unavailable` when it did not (see `unavailable_reason`); `pending` while the registry is still fetching it; `not_requested` for the Basic tier. */
  status: "not_requested" | "pending" | "delivered" | "unavailable" | (string & {}) | null;
  /** The tier the workflow ordered. */
  tier_requested: "basic" | "shareholders" | "ubo" | (string & {}) | null;
  /** The tier the registry delivered (and that is billed). A UBO request answered with direct shareholders only is `shareholders`. */
  tier_delivered: "basic" | "shareholders" | "ubo" | (string & {}) | null;
  /** Why a requested ownership tier was not delivered. Null unless `status` is `unavailable` or `pending`. */
  unavailable_reason:
    | "no_owners_on_record"
    | "no_natural_person_owner"
    | "ownership_section_unavailable"
    | "company_not_found"
    | "ambiguous_company_match"
    | "missing_registration_number"
    | "entity_type_not_covered"
    | "provider_unavailable"
    | "other"
    | (string & {})
    | null;
  /** True when the direct shareholders' stated stakes add up to 100% (within one percentage point of rounding); false when they do not; null when ownership was not delivered or a stake is not stated. */
  direct_ownership_complete: boolean | null;
  /** Parts of the ownership chain the registry could not resolve, for example no group structure on record above the direct owners. */
  unresolved: KYBRegistryOwnershipUnresolved[];
}

export interface KYBRegistryOwnershipUnresolved {
  reason?: string;
  section?: string | null;
}

/** What an owner holds, in the same shape for every country and registry source. Null when the registry states no holding. A band (for example a UK PSC's 25-50%) is not a stake: `percentage` is null and the band stays in `ownership_min_shares` / `ownership_max_shares`. */
export interface KYBRegistryShareholding {
  /** Share class or type as the registry names it. */
  share_class: string | null;
  /** Number of shares held. */
  number_of_shares: number | null;
  /** ISO 4217 currency of the values below. */
  currency: string | null;
  /** Nominal value per share. */
  nominal_value: number | null;
  /** Total value of the holding. */
  total_value: number | null;
  /** Exact stake in percent, to four decimal places. */
  percentage: number | null;
}

